// Typed loader and helpers for /data/chromium/components.json, generated by
// importer/dir_metadata.mjs from Chromium's 3,484 DIR_METADATA + COMMON_METADATA
// files joined against CVEs, VRP rewards, fuzzers, treemap safety metrics,
// commit_rates hash buckets, and accretion survivorship.

export interface ComponentRootDir {
  path: string;
  lines: number;
  files: number;
  commits12m: number;
  fuzzers: number;
  accretionDir: string;
}

export interface ComponentCodeStats {
  files: number;
  lines: number;
  langs: {
    cpp: number;
    rust: number;
    jsTs: number;
    javaKt: number;
    mojom: number;
    other: number;
  };
  rawPtr: number;
  rawRef: number;
  dangling: number;
  unsafeBuffers: number;
  unsafeBufferLines: number;
  unsafeLibc: number;
  unsafeTodo: number;
  disabledTests: number;
  tests: number;
  todos: number;
}

export interface ComponentCommitStats {
  all: number;
  last12m: number;
  prev12m: number;
  quarterly: number[];
}

export interface ComponentFuzzerItem {
  name: string;
  file: string;
  line: number;
  type: "FUZZ_TEST" | "fuzzer_test";
}

export interface ComponentFuzzerStats {
  count: number;
  fuzzTests: number;
  fuzzTargets: number;
  items: ComponentFuzzerItem[];
}

export interface ComponentCveStats {
  total: number;
  recent24m: number;
  vrpTotal: number;
  vrpRecent24m: number;
  vrpCount: number;
  vrpMax: number;
  severities: {
    Critical: number;
    High: number;
    Medium: number;
    Low: number;
  };
  topCwes: Array<{ cweId: string; count: number; vrp: number }>;
  byYear: Array<{ year: number; count: number; vrp: number }>;
}

export interface ComponentAccretionStats {
  lines: number;
  recent: number;
  yearAgo: number;
  reworked: number;
  medianAge: number;
  reviewedCoverage: number;
  busFactor: number;
  busFactorReviewed: number;
  authors: number;
  label: string;
  dirs: string[];
}

export interface ComponentEntry {
  name: string;
  inDirMetadata: boolean;
  submodule: { repo: string; label: string } | null;
  teams: string[];
  primaryTeam: string;
  os: string[];
  bugPublicIds: number[];
  bugIds: number[];
  dirMetaCount: number;
  rootCount: number;
  ownedDirCount: number;
  roots: ComponentRootDir[];
  code: ComponentCodeStats;
  commits: ComponentCommitStats;
  fuzzers: ComponentFuzzerStats;
  cves: ComponentCveStats;
  accretion: ComponentAccretionStats | null;
  // Derived convenience fields for table sorting & executive callouts:
  lines: number;
  cppLines: number;
  commits12m: number;
  cveTotal: number;
  vrpTotal: number;
  unsafeBuffers: number;
  fuzzerCount: number;
  isHighVrpUnfuzzed: boolean;
}

export interface TeamEntry {
  email: string;
  components: string[];
  componentCount: number;
  os: string[];
  bugPublicIds: number[];
  bugIds: number[];
  dirMetaCount: number;
  rootCount: number;
  ownedDirCount: number;
  roots: ComponentRootDir[];
  code: ComponentCodeStats;
  commits: ComponentCommitStats;
  fuzzers: ComponentFuzzerStats;
  cves: ComponentCveStats;
  accretion: ComponentAccretionStats | null;
  // Derived convenience fields for table sorting:
  lines: number;
  cppLines: number;
  commits12m: number;
  cveTotal: number;
  vrpTotal: number;
  unsafeBuffers: number;
  fuzzerCount: number;
}

export interface ComponentsDataset {
  generatedAt: string;
  quarterLabels: string[];
  cveStartYear: number;
  cveEndYear: number;
  stats: {
    dirMetadataFiles: number;
    commonMetadataMixins: number;
    mixinEdgesResolved: number;
    backfilledViaBuganizer: number;
    synthesizedBuganizerOnly: number;
    dirMetadataComponents: number;
    totalComponents: number;
    uniqueTeams: number;
    matchedFuzzers: number;
    totalFuzzers: number;
    matchedCveLinks: number;
  };
  components: ComponentEntry[];
  componentsByName: Map<string, ComponentEntry>;
  componentsByLower: Map<string, ComponentEntry>;
  teams: TeamEntry[];
  teamsByEmail: Map<string, TeamEntry>;
}

const emptyCode = (): ComponentCodeStats => ({
  files: 0,
  lines: 0,
  langs: { cpp: 0, rust: 0, jsTs: 0, javaKt: 0, mojom: 0, other: 0 },
  rawPtr: 0,
  rawRef: 0,
  dangling: 0,
  unsafeBuffers: 0,
  unsafeBufferLines: 0,
  unsafeLibc: 0,
  unsafeTodo: 0,
  disabledTests: 0,
  tests: 0,
  todos: 0,
});

function unpackCode(c?: number[]): ComponentCodeStats {
  if (!c || !c.length) return emptyCode();
  return {
    files: c[0] || 0,
    lines: c[1] || 0,
    langs: {
      cpp: c[2] || 0,
      rust: c[3] || 0,
      jsTs: c[4] || 0,
      javaKt: c[5] || 0,
      mojom: c[6] || 0,
      other: c[7] || 0,
    },
    rawPtr: c[8] || 0,
    rawRef: c[9] || 0,
    dangling: c[10] || 0,
    unsafeBuffers: c[11] || 0,
    unsafeBufferLines: c[12] || 0,
    unsafeLibc: c[13] || 0,
    unsafeTodo: c[14] || 0,
    disabledTests: c[15] || 0,
    tests: c[16] || 0,
    todos: c[17] || 0,
  };
}

function unpackCommits(m: any[] | undefined, qLen: number): ComponentCommitStats {
  if (!m || !m.length) {
    return { all: 0, last12m: 0, prev12m: 0, quarterly: new Array(qLen).fill(0) };
  }
  const q = Array.isArray(m[3]) && m[3].length ? m[3] : new Array(qLen).fill(0);
  return {
    all: m[0] || 0,
    last12m: m[1] || 0,
    prev12m: m[2] || 0,
    quarterly: q,
  };
}

function unpackFuzzers(f?: any[]): ComponentFuzzerStats {
  if (!f || !f.length) {
    return { count: 0, fuzzTests: 0, fuzzTargets: 0, items: [] };
  }
  const items: ComponentFuzzerItem[] = (f[3] || []).map((it: any[]) => ({
    name: it[0] || "",
    file: it[1] || "",
    line: it[2] || 1,
    type: it[3] === 1 ? "FUZZ_TEST" : "fuzzer_test",
  }));
  return {
    count: f[0] || 0,
    fuzzTests: f[1] || 0,
    fuzzTargets: f[2] || 0,
    items,
  };
}

function unpackCves(v: any[] | undefined, startYear: number, endYear: number): ComponentCveStats {
  const yearsCount = Math.max(0, endYear - startYear + 1);
  if (!v || !v.length) {
    return {
      total: 0,
      recent24m: 0,
      vrpTotal: 0,
      vrpRecent24m: 0,
      vrpCount: 0,
      vrpMax: 0,
      severities: { Critical: 0, High: 0, Medium: 0, Low: 0 },
      topCwes: [],
      byYear: Array.from({ length: yearsCount }, (_, idx) => ({
        year: startYear + idx,
        count: 0,
        vrp: 0,
      })),
    };
  }
  const sev = v[6] || [0, 0, 0, 0];
  const topCwes = (v[7] || []).map((row: any[]) => ({
    cweId: String(row[0]),
    count: row[1] || 0,
    vrp: row[2] || 0,
  }));
  const rawYears = v[8] || [];
  const byYear = Array.from({ length: yearsCount }, (_, idx) => ({
    year: startYear + idx,
    count: rawYears[idx]?.[0] || 0,
    vrp: rawYears[idx]?.[1] || 0,
  }));
  return {
    total: v[0] || 0,
    recent24m: v[1] || 0,
    vrpTotal: v[2] || 0,
    vrpRecent24m: v[3] || 0,
    vrpCount: v[4] || 0,
    vrpMax: v[5] || 0,
    severities: {
      Critical: sev[0] || 0,
      High: sev[1] || 0,
      Medium: sev[2] || 0,
      Low: sev[3] || 0,
    },
    topCwes,
    byYear,
  };
}

function unpackRoots(r?: any[]): ComponentRootDir[] {
  if (!r || !r.length) return [];
  return r.map((row: any[]) => {
    const path = row[0] || "";
    const accRaw = row[5] || "";
    return {
      path,
      lines: row[1] || 0,
      files: row[2] || 0,
      commits12m: row[3] || 0,
      fuzzers: row[4] || 0,
      accretionDir: accRaw === "=" ? path : accRaw,
    };
  });
}

function unpackAccretion(a?: any[]): ComponentAccretionStats | null {
  if (!a || !a.length) return null;
  return {
    lines: a[0] || 0,
    recent: a[1] || 0,
    yearAgo: a[2] || 0,
    reworked: a[3] || 0,
    medianAge: a[4] || 0,
    reviewedCoverage: a[5] || 0,
    busFactor: a[6] || 0,
    busFactorReviewed: a[7] || 0,
    authors: a[8] || 0,
    label: a[9] || "Growing",
    dirs: a[10] || [],
  };
}

// Convert "Blink>WebAudio" -> "/components/Blink/WebAudio" for clean hierarchical URLs,
// while decodeComponentSlug accepts BOTH "/components/Blink/WebAudio" and "/components/Blink>WebAudio".
export function componentPath(name: string): string {
  const parts = name
    .split(">")
    .map((p) => encodeURIComponent(p.trim()))
    .filter(Boolean);
  return `/components/${parts.join("/")}`;
}

export function teamPath(email: string): string {
  return `/teams/${encodeURIComponent(email.trim().toLowerCase())}`;
}

export function normalizeSlugToComponentCandidates(slugParam: string | string[] | undefined): string[] {
  if (!slugParam) return [];
  const rawParts = (Array.isArray(slugParam) ? slugParam : [slugParam])
    .flatMap((part) => {
      try {
        return decodeURIComponent(part);
      } catch {
        return part;
      }
    })
    .filter(Boolean);

  if (rawParts.length === 0) return [];
  const joinedGreater = rawParts
    .flatMap((p) => p.split("/"))
    .filter(Boolean)
    .join(">");
  const joinedRaw = rawParts.join("/");
  return [...new Set([joinedGreater, joinedRaw])];
}

let datasetPromise: Promise<ComponentsDataset> | null = null;

export function fetchComponentsDataset(): Promise<ComponentsDataset> {
  if (!datasetPromise) {
    datasetPromise = (async () => {
      const response = await fetch("/data/chromium/components.json");
      if (!response.ok) {
        throw new Error(`Failed to fetch /data/chromium/components.json: ${response.status}`);
      }
      const raw = await response.json();
      const quarterLabels: string[] = raw.quarterLabels || [];
      const startYear: number = raw.cveStartYear || 2016;
      const endYear: number = raw.cveEndYear || 2026;

      const components: ComponentEntry[] = (raw.components || []).map((item: any) => {
        const code = unpackCode(item.c);
        const commits = unpackCommits(item.m, quarterLabels.length);
        const fuzzers = unpackFuzzers(item.f);
        const cves = unpackCves(item.v, startYear, endYear);
        const teams: string[] = item.t || [];
        const dc = item.dc || [0, 0, 0];
        const inDirMetadata = item.dm === 1;
        const isHighVrpUnfuzzed =
          inDirMetadata &&
          fuzzers.count === 0 &&
          code.langs.cpp >= 5000 &&
          (cves.vrpTotal >= 25000 || cves.total >= 10);

        return {
          name: item.n,
          inDirMetadata,
          submodule: item.sub ? { repo: item.sub[0], label: item.sub[1] } : null,
          teams,
          primaryTeam: teams[0] || "",
          os: item.os || [],
          bugPublicIds: item.bp || [],
          bugIds: item.bi || [],
          dirMetaCount: dc[0] || 0,
          rootCount: dc[1] || 0,
          ownedDirCount: dc[2] || 0,
          roots: unpackRoots(item.r),
          code,
          commits,
          fuzzers,
          cves,
          accretion: unpackAccretion(item.a),
          lines: code.lines,
          cppLines: code.langs.cpp,
          commits12m: commits.last12m,
          cveTotal: cves.total,
          vrpTotal: cves.vrpTotal,
          unsafeBuffers: code.unsafeBuffers,
          fuzzerCount: fuzzers.count,
          isHighVrpUnfuzzed,
        };
      });

      const componentsByName = new Map<string, ComponentEntry>();
      const componentsByLower = new Map<string, ComponentEntry>();
      for (const comp of components) {
        componentsByName.set(comp.name, comp);
        componentsByLower.set(comp.name.toLowerCase(), comp);
      }

      const teams: TeamEntry[] = (raw.teams || []).map((item: any) => {
        const code = unpackCode(item.c);
        const commits = unpackCommits(item.m, quarterLabels.length);
        const fuzzers = unpackFuzzers(item.f);
        const cves = unpackCves(item.v, startYear, endYear);
        const comps: string[] = item.cp || [];
        const dc = item.dc || [0, 0, 0];

        return {
          email: item.e,
          components: comps,
          componentCount: comps.length,
          os: item.os || [],
          bugPublicIds: item.bp || [],
          bugIds: item.bi || [],
          dirMetaCount: dc[0] || 0,
          rootCount: dc[1] || 0,
          ownedDirCount: dc[2] || 0,
          roots: unpackRoots(item.r),
          code,
          commits,
          fuzzers,
          cves,
          accretion: unpackAccretion(item.a),
          lines: code.lines,
          cppLines: code.langs.cpp,
          commits12m: commits.last12m,
          cveTotal: cves.total,
          vrpTotal: cves.vrpTotal,
          unsafeBuffers: code.unsafeBuffers,
          fuzzerCount: fuzzers.count,
        };
      });

      const teamsByEmail = new Map<string, TeamEntry>();
      for (const t of teams) {
        teamsByEmail.set(t.email.toLowerCase(), t);
      }

      return {
        generatedAt: raw.generatedAt || "",
        quarterLabels,
        cveStartYear: startYear,
        cveEndYear: endYear,
        stats: raw.stats,
        components,
        componentsByName,
        componentsByLower,
        teams,
        teamsByEmail,
      };
    })().catch((err) => {
      datasetPromise = null;
      throw err;
    });
  }
  return datasetPromise;
}
